import{d as g,C as o,o as h,c as u,j as i,a as e,E as a,a3 as d}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸·第31章","description":"《中庸》第 31 章——唯天下至圣：聪明睿知、宽裕温柔、发强刚毅、齐庄中正、文理密察；溥博渊泉而时出之，故曰配天。","frontmatter":{"title":"中庸·第31章","description":"《中庸》第 31 章——唯天下至圣：聪明睿知、宽裕温柔、发强刚毅、齐庄中正、文理密察；溥博渊泉而时出之，故曰配天。","category":"guide","aliases":["第31章","中庸第31章","唯天下至圣"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-31.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-31.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-31.md"},b=g({...m,setup(p){const r=[{id:"wude",label:"聪明睿知 · 宽裕温柔 · 发强刚毅 · 齐庄中正 · 文理密察",showLabel:!0,sentences:[["唯天下至圣，为能聪明睿知，足以有",{text:"临",glossary:"lin"},"也；宽裕温柔，足以有容也；发强刚毅，足以有执也；",{text:"齐庄中正",glossary:"qizhuang"},"，足以有敬也；文理密察，足以有别也。"]],note:"「唯天下至圣，为能聪明睿知」——只有天下至圣，才能聪明睿智。其五德各有所用：「聪明睿知，足以有临也」（足以临下）；「宽裕温柔，足以有容也」（足以容众）；「发强刚毅，足以有执也」（足以持守）；「齐庄中正，足以有敬也」（足以恭敬）；「文理密察，足以有别也」（足以辨别）。五者一一相配。"},{id:"pubo",label:"溥博渊泉，而时出之 · 溥博如天，渊泉如渊",showLabel:!0,sentences:[[{text:"溥博渊泉",glossary:"puboyuanquan"},"，而",{text:"时出之",glossary:"shichuzhi"},"。溥博如天，渊泉如渊。"]],note:"「溥博渊泉，而时出之」——其德周遍广大（溥博）而深如渊泉，又随时流出。「溥博如天，渊泉如渊」——广大如天，深厚如渊。"},{id:"minjing",label:"见而民莫不敬 · 声名洋溢乎中国，施及蛮貊",showLabel:!0,sentences:[["见而民莫不敬，言而民莫不信，行而民莫不说。是以声名洋溢乎中国，施及",{text:"蛮貊",glossary:"manmo"},"；舟车所至，人力所通；天之所覆，地之所载，日月所照，霜露所",{text:"队",glossary:"zhui"},"；"]],note:"其德之效：「见而民莫不敬，言而民莫不信，行而民莫不说（悦）」——百姓见之无不敬、闻其言无不信、见其行无不悦。故「声名洋溢乎中国，施及蛮貊」——声名充满中国，延及边远；「舟车所至，人力所通，天之所覆，地之所载，日月所照，霜露所队（坠）」——凡舟车人迹所至之处。"},{id:"peitian",label:"凡有血气者莫不尊亲 · 故曰配天",showLabel:!0,sentences:[["凡有血气者，莫不尊亲，故曰",{text:"配天",glossary:"peitian"},"。"]],note:"「凡有血气者，莫不尊亲，故曰配天」——凡有血气之人，无不尊崇亲近他，所以说他「配天」。此章以至圣之德「配天」作收。"}],s=[{id:"lin",term:"临",pinyin:"lín",meaning:"朱注：「临，谓居上而临下也。」"},{id:"qizhuang",term:"齐庄中正",pinyin:"zhāi zhuāng zhōng zhèng",meaning:"齐：读 zhāi。庄敬中正，足以有敬。朱注谓「聪敏睿知，生知之质；其下四者，乃仁义礼知之德」。"},{id:"puboyuanquan",term:"溥博渊泉",pinyin:"pǔ bó yuān quán",meaning:"朱注：「溥博，周遍而广阔也；渊泉，静深而有本也。」"},{id:"shichuzhi",term:"时出之",pinyin:"shí chū zhī",meaning:"朱注：「言五者之德，充积于中，而以时发见于外也。」"},{id:"manmo",term:"蛮貊",pinyin:"mán mò",meaning:"南方曰蛮，北方曰貊。泛指远方之族。"},{id:"zhui",term:"队",pinyin:"zhuì",meaning:"同「坠」。霜露所队，即霜露所落之处。"},{id:"peitian",term:"配天",pinyin:"pèi tiān",meaning:"朱注：「言其德之所及，广大如天也。」"}];return(c,n)=>{const l=o("DaoTextReading"),t=o("DaoKeywordCards");return h(),u("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第31章",tabindex:"-1"},[e("中庸·第31章 "),i("a",{class:"header-anchor",href:"#中庸·第31章","aria-label":'Permalink to "中庸·第31章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,[e("第三十一章说「至圣」的五德与它们的发用："),i("strong",null,"聪明睿知／宽裕温柔／发强刚毅／齐庄中正／文理密察"),e("；「溥博渊泉，而时出之」；末以声名所及与「故曰配天」作结。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),a(l,{colophon:"五德 · 溥博渊泉而时出之 · 故曰配天",tone:"ink",sections:r,glossary:s,"default-mode":"slips","aria-label":"中庸·第31章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(t,{items:[{term:"聪明睿知",pinyin:["cōng","míng","ruì","zhì"],meaning:"朱注：「生知之质。」知读 zhì（智）——这是资质，不是学来的。"},{term:"宽裕温柔",pinyin:["kuān","yù","wēn","róu"],meaning:"足以有容——仁。"},{term:"发强刚毅",pinyin:["fā","qiáng","gāng","yì"],meaning:"足以有执——义。"},{term:"齐庄中正",pinyin:["zhāi","zhuāng","zhōng","zhèng"],meaning:"齐：读 zhāi。庄敬中正，足以有敬——礼。"},{term:"文理密察",pinyin:["wén","lǐ","mì","chá"],meaning:"足以有别——智。"},{term:"溥博渊泉",pinyin:["pǔ","bó","yuān","quán"],meaning:"周遍广阔而静深有本——德充积于中。"}]}),a(t,{items:[{term:"时出之",pinyin:["shí","chū","zhī"],meaning:"按时发见于外。德积于中，发用当其时——与第 2 章「发而皆中节」、第 25 章「时措之宜」同旨。"},{term:"蛮貊",pinyin:["mán","mò"],meaning:"南方曰蛮，北方曰貊。泛指远方之族。"},{term:"队",pinyin:["zhuì"],meaning:"同「坠」。「霜露所队」即霜露所落之处。"},{term:"配天",pinyin:["pèi","tiān"],meaning:"德之所及广大如天。"}]}),n[4]||(n[4]=d('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>五德</strong>：只有天下至圣的人，才能聪明睿智，足以居上临下；宽裕温柔，足以包容；发强刚毅，足以执守；庄敬中正，足以有敬；文理密察，足以辨别。</p><p><strong>溥博渊泉</strong>：周遍广阔、静深有本，而按时发见于外。溥博如天，渊泉如渊。</p><p><strong>见而民莫不敬</strong>：他一出现，人民无不敬；他一开口，人民无不相信；他一行动，人民无不喜悦。因此声名洋溢于中国，远及蛮貊；凡是舟车所到、人力所通、天所覆盖、地所承载、日月所照、霜露所落之处——</p><p><strong>凡有血气者莫不尊亲</strong>：凡有血气的，无不尊亲他，所以说他配天。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第三十一章说「至圣」，分三层：</p><ol><li><strong>五德</strong>：聪明睿知（足以有临）、宽裕温柔（有容）、发强刚毅（有执）、齐庄中正（有敬）、文理密察（有别）</li><li><strong>德的蓄与发</strong>：溥博渊泉，而时出之；溥博如天，渊泉如渊</li><li><strong>德的效验</strong>：见而敬、言而信、行而说；声名洋溢及于蛮貊；凡有血气者莫不尊亲，故曰「配天」</li></ol><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>五德的结构值得注意</strong>：朱注说「聪明睿知，<strong>生知之质</strong>；其下四者，乃<strong>仁义礼知之德</strong>」——第一条是资质，后四条正配仁（容）、义（执）、礼（敬）、智（别）。<strong>这一章因此可以看作「仁、义、礼、智」的另一种列法。</strong></li><li><strong>「溥博渊泉，而时出之」是德的双面</strong>：既要「溥博」（周遍广阔，够大），也要「渊泉」（静深有本，够深），然后<strong>按时发露</strong>。只大不深则虚，只深不露则废。</li><li><strong>它与第 2 章遥相呼应</strong>：第 2 章说「发而皆中节」，本章说「时出之」——<strong>都是「恰好在该出来的时候出来」</strong>。</li><li><strong>「见而民莫不敬，言而民莫不信，行而民莫不说」的次序</strong>：见（存在本身）→ 言 → 行。<strong>最重的其实是第一项：他在那里，人便敬。</strong></li><li><strong>「配天」承第 26、30 章</strong>：从「博厚配地，高明配天」到「小德川流，大德敦化」，再到这里的「配天」——全篇末尾几章反复用天地为喻，讲的是德所及的广度。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>五德当自省清单</strong>：聪明睿知（看事情看不透）／宽裕温柔（容不容得下人）／发强刚毅（守不守得住）／齐庄中正（有没有庄严与中正）／文理密察（分不分得清）。</li><li><strong>「溥博渊泉」两头都要</strong>：光有广度和光有深度都不成，还要「时出之」。</li><li><strong>「见而民莫不敬」</strong>：一个人的存在本身就在起作用——这部分通常自己看不见，却最要紧。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>至圣的人，有五种德：<strong>聪明睿智（能居上临下）、宽裕温柔（能包容）、发强刚毅（能守持）、庄敬中正（能有敬）、文理密察（能辨别）。</strong></p><p>这些德<strong>周遍广阔、静深有本</strong>，并且<strong>按时发露</strong>——像天一样广，像渊一样深。</p><p>于是他一出现，人便敬；他一开口，人便信；他一行动，人便悦。声名传到远方，凡有血气者莫不尊亲——<strong>所以称他配天。</strong></p><p>这一章讲的不是「能力」，是「德到什么程度，能到什么程度」。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>五德（聪明睿知／宽裕温柔／发强刚毅／齐庄中正／文理密察）——我最缺哪一条？</li><li>「溥博渊泉，而时出之」——我够广吗？够深吗？该出的时候出了吗？</li><li>「见而民莫不敬」——我的「存在本身」，正在起什么作用？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-30">中庸·第30章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-32">中庸·第32章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',25))])}}});export{z as __pageData,b as default};
